import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import HomePage from './components/HomePage/HomePage';
import ProductList from './components/ProductList/ProductList';
import OrderSummary from './components/OrderSummary/OrderSummary';
import SuccessPage from './components/SuccessPage/SuccessPage';
import axios from 'axios';
import './App.css';

const App = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await axios.get('/api/storage');
        const productsWithQuantity = response.data.storage.map(product => ({
          ...product,
          quantity: 0
        }));
        setProducts(productsWithQuantity);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  const handleQuantityChange = (productName, change) => {
    setProducts(prevProducts =>
      prevProducts.map(product =>
        product.name === productName
          ? {
              ...product,
              quantity: Math.max(
                0,
                Math.min(product.quantity + change, product.stock)
              )
            }
          : product
      )
    );
  };

  const handleCheckout = async () => {
    try {
      const orderItems = products
        .filter(product => product.quantity > 0)
        .map(({ name, quantity }) => ({ name, quantity }));

      await axios.post('/api/order', { items: orderItems });
      window.location.href = '/success';
    } catch (err) {
      alert(`Order failed: ${err.response?.data?.error || err.message}`);
    }
  };

  const total = products.reduce(
    (sum, product) => sum + product.price * product.quantity,
    0
  );

  return (
    <Router>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route 
          path="/products" 
          element={
            <div className="store-container">
              {loading ? (
                <div>Loading...</div>
              ) : error ? (
                <div>Error: {error}</div>
              ) : (
                <>
                  <ProductList 
                    products={products} 
                    onQuantityChange={handleQuantityChange} 
                  />
                  <OrderSummary 
                    cart={products} 
                    total={total} 
                    onCheckout={handleQuantityChange}
                    onPlaceOrder={handleCheckout}
                  />
                </>
              )}
            </div>
          } 
        />
        <Route path="/success" element={<SuccessPage />} />
      </Routes>
    </Router>
  );
};

export default App;
